mapper.select:
SELECT a.id, a.patient_id, p.name AS patient_name, a.appointment_date, a.department, a.doctor, a.status, a.reason FROM clinic_appointment a LEFT JOIN clinic_patient p ON p.id = a.patient_id
a.patient_id = #{patientId}
AND a.status = #{status}
AND a.doctor = #{doctor}
ORDER BY a.appointment_date DESC

mapper.update:
UPDATE clinic_appointment
SET status = 'CANCELLED',
    reason = #{reason}
WHERE id = #{id}
